// Valida el cuerpo {"preguntaA":"…","preguntaB":"…"} antes de gastar cuota.
const body = $('Webhook').first().json.body ?? {};
const { modeloEmbeddings } = $('Configuración').first().json;
const campos = ['preguntaA', 'preguntaB'];
const textos = {};
for (const campo of campos) {
  const valor = body[campo];
  if (typeof valor !== 'string' || !valor.trim()) {
    throw new Error(`Falta "${campo}" o no es un texto`);
  }
  if (valor.trim().length > 1000) {
    throw new Error(`"${campo}" supera los 1000 caracteres`);
  }
  textos[campo] = valor.trim();
}
if (textos.preguntaA.toLowerCase() === textos.preguntaB.toLowerCase()) {
  throw new Error('preguntaA y preguntaB deben ser dos textos diferentes');
}
// Un ítem por pregunta: «Generar embedding» corre una vez por ítem, siempre con el mismo modelo.
return campos.map((campo) => ({
  json: {
    campo,
    texto: textos[campo],
    cuerpo: {
      model: modeloEmbeddings,
      input: textos[campo],
      input_type: 'query',
      encoding_format: 'float',
    },
  },
}));

// Comprueba que cada respuesta traiga un vector válido y que los dos vectores sean compatibles.
const { modeloEmbeddings, dimensionVector } = $('Configuración').first().json;
const preguntas = $('Validar preguntas').all();
const respuestas = $input.all();
if (respuestas.length !== preguntas.length) {
  throw new Error(`Se esperaban ${preguntas.length} respuestas de OpenRouter y llegaron ${respuestas.length}`);
}
// «Generar embedding» procesa un ítem por pregunta y conserva el orden.
const vectores = respuestas.map((item, i) => {
  const { campo, texto } = preguntas[i].json;
  const resp = item.json;
  const body = resp.body ?? {};
  if (resp.statusCode !== 200 || body.error) {
    const codigo = body.error?.code ?? resp.statusCode;
    const detalle = body.error?.message ?? JSON.stringify(body).slice(0, 300);
    throw new Error(`OpenRouter respondió HTTP ${codigo} al generar el embedding de ${campo}: ${detalle}`);
  }
  const vector = body.data?.[0]?.embedding;
  if (!Array.isArray(vector) || vector.length === 0) {
    throw new Error(`OpenRouter no devolvió un vector para ${campo}`);
  }
  if (!vector.every(Number.isFinite)) {
    throw new Error(`El vector de ${campo} tiene valores que no son números finitos`);
  }
  const norma = Math.sqrt(vector.reduce((suma, x) => suma + x * x, 0));
  if (norma === 0) {
    throw new Error(`El vector de ${campo} es todo ceros y no se puede comparar`);
  }
  return { campo, texto, modelo: body.model ?? modeloEmbeddings, vector, norma };
});
const [a, b] = vectores;
if (a.vector.length !== b.vector.length) {
  throw new Error(`Los vectores no son compatibles: tienen ${a.vector.length} y ${b.vector.length} dimensiones`);
}
if (a.vector.length !== dimensionVector) {
  throw new Error(`Los vectores tienen ${a.vector.length} dimensiones y el modelo debe dar ${dimensionVector}`);
}
if (a.modelo !== b.modelo) {
  throw new Error(`Los vectores salieron de modelos distintos: ${a.modelo} y ${b.modelo}`);
}
return [{ json: { a, b } }];

// Similitud coseno = producto punto / (norma A × norma B). Va de -1 a 1; cuanto más cerca de 1, más parecidas.
// Es solo aritmética sobre los vectores: aquí no participa ningún LLM.
const { a, b } = $input.first().json;
let productoPunto = 0;
for (let i = 0; i < a.vector.length; i++) {
  productoPunto += a.vector[i] * b.vector[i];
}
const similitud = productoPunto / (a.norma * b.norma);
return [{
  json: {
    preguntaA: a.texto,
    preguntaB: b.texto,
    similitud: Math.round(similitud * 10000) / 10000,
    medida: 'coseno',
    modelo: $('Configuración').first().json.modeloEmbeddings,
    dimensiones: a.vector.length,
  },
}];

// Normaliza el error de cualquier paso. Si falló la validación de la entrada es 400; si no, 500.
const e = $input.first().json.error;
let mensaje = typeof e === 'string' ? e : (e?.message ?? JSON.stringify(e));
if (e && typeof e === 'object' && e.code && !String(mensaje).includes(e.code)) {
  mensaje += ` (${e.code})`;
}
const status = $prevNode.name === 'Validar preguntas' ? 400 : 500;
return [{ json: { status, error: `Falló el paso «${$prevNode.name}»: ${mensaje}` } }];
